const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const label=(c,s,x,y,color='#f1d89e',size=12)=>{c.font=`bold ${size}px "PingFang SC",sans-serif`;c.textAlign='center';c.lineWidth=3;c.strokeStyle='#20312c';c.strokeText(s,x,y);c.fillStyle=color;c.fillText(s,x,y);};
function sprite(c,im,key,n,x,y,scale=1,flip=false){if(!im?.complete)return false;const meta=BATTLE_ATLASES[key],f=meta.frames[n],cw=im.width/meta.cols,ch=im.height/meta.rows;c.save();c.imageSmoothingEnabled=false;c.translate(x,y);if(flip!==!!f.flip)c.scale(-1,1);const [sx,sy,w,h]=f.rect||[n%meta.cols*cw,Math.floor(n/meta.cols)*ch,cw,ch];c.drawImage(im,sx,sy,w,h,-f.x*scale,-f.y*scale,w*scale,h*scale);c.restore();return true;}
function health(c,a,y,w=42){if(a.hp>=a.max&&!a.flash)return;c.fillStyle='#28312a';c.fillRect(a.x-w/2-1,y-1,w+2,5);c.fillStyle=a.hp/a.max<.3?'#d98b73':'#b9c793';c.fillRect(a.x-w/2,y,w*clamp(a.hp/a.max,0,1),3);}
export function drawKeeperBattle(c,b,p,assets,direction){const q=b.swing,w=b.pulseWave;if(!q&&!w)return false;const angle=q?.angle,face=q?(Math.abs(Math.cos(angle))>Math.abs(Math.sin(angle))?(Math.cos(angle)>0?'right':'left'):(Math.sin(angle)>0?'down':'up')):direction,row=['down','left','right','up'].indexOf(face);if(q){const frame=q.age<.05?0:q.age<.1?1:q.age<.16?2:q.age<.22?3:q.age<.31?4:5;return sprite(c,assets?.sword,'sword',Math.max(0,row)*6+frame,p.x,p.y,BATTLE_ATLASES.sword.scale);}return sprite(c,assets?.lantern,'lantern',Math.max(0,row),p.x,p.y,BATTLE_ATLASES.lantern.scale);}
export function frontLayers(c,b,p,assets={},reduced=false){const f=b.front;if(!f)return [];const layers=[],add=(a,fn)=>layers.push({y:a.y,draw:fn});
 for(const flag of f.flags){const visible=f.phase==='planning'||f.panelOpen||flag.contested||Math.hypot(p.x-flag.x,p.y-flag.y)<140;if(visible){c.save();c.strokeStyle=flag.contested?'#efc77a88':'#a8bea344';c.lineWidth=1;c.setLineDash([4,8]);c.beginPath();c.arc(flag.x,flag.y,95,0,Math.PI*2);c.stroke();c.restore();}add(flag,()=>{c.save();c.translate(flag.x,flag.y);if(!reduced)c.transform(1,0,Math.sin(b.time*1.6)*.012,1,0,0);sprite(c,assets.facilities,'facilities',flag.control>50?2:3,0,0,.19);c.restore();c.save();c.lineWidth=2;c.strokeStyle=flag.contested?'#f9d78b':flag.control<100?'#ce8a7f':'#b0c19e';c.beginPath();c.ellipse(flag.x,flag.y+4,18,7,0,-Math.PI/2,-Math.PI/2+Math.PI*2*flag.control/100);c.stroke();c.restore();if(visible)label(c,`${flag.name} ${Math.ceil(flag.control)}%`,flag.x,flag.y-116);if(flag.contested){c.globalAlpha=reduced?1:.6+Math.sin(b.time*5)*.3;label(c,'争夺',flag.x,flag.y-104,'#f4d38d');c.globalAlpha=1;}});}
 const list=f.phase==='planning'?FRONT_SLOTS.flatMap(p=>f.loadout[p.id]?[{...p,type:f.loadout[p.id],hp:BUILDINGS[f.loadout[p.id]].hp,max:BUILDINGS[f.loadout[p.id]].hp}]:[]):f.structures;
 if(f.phase==='planning')for(const a of FRONT_SLOTS){c.strokeStyle='#d7c38a99';c.lineWidth=1;c.strokeRect(a.x-37,a.y-18,74,34);label(c,a.name,a.x,a.y+30);}
 for(const a of list)add(a,()=>{c.save();c.globalAlpha=a.hp>0?1:.35;if(a.type==='tower'){sprite(c,assets.facilities,'facilities',4,a.x,a.y,.20);c.save();c.translate(a.x,a.y-70);const angle=a.angle||0;c.rotate(Math.sin(angle)*.22);sprite(c,assets.facilities,'facilities',5,0,0,.14,Math.cos(angle)<0);c.restore();if(a.action?.age<.4){const r=3+7*a.action.age/.4;c.fillStyle='#ffe4a1';c.globalAlpha=.65;c.beginPath();c.arc(a.x+Math.cos(angle)*16,a.y-94+Math.sin(angle)*7,r,0,Math.PI*2);c.fill();}}
  else {const im=assets.tactics;if(im?.complete)c.drawImage(im,im.width/2,im.height/2,im.width/2,im.height/2,a.x-60,a.y-72,120,80);if(a.hp/a.max<.66){c.strokeStyle='#4a352a';c.lineWidth=3;c.beginPath();c.moveTo(a.x-16,a.y-45);c.lineTo(a.x-8,a.y-28);c.lineTo(a.x-19,a.y-18);c.stroke();}if(a.hp/a.max<.33){c.fillStyle='#c09656';for(let i=0;i<6;i++)c.fillRect(a.x-34+i*13,a.y+3+(i%2)*4,8,3);}}
 c.restore();health(c,a,a.y-(a.type==='tower'?118:78),46);});
 for(const a of f.units)add(a,()=>{c.save();c.globalAlpha=a.hp>0?1:.3;const q=a.action,frame=a.type==='shield'?(a.block>0?3:q?(q.age<.22?1:q.age<.38?2:0):0):(q?(q.age<.36?1:q.age<.48?2:3):0);const recoil=a.block>0?(reduced?0:-3):0;sprite(c,assets.squad,'squad',(a.type==='shield'?0:4)+frame,a.x+recoil,a.y,BATTLE_ATLASES.squad.scale,Math.cos(a.angle||0)<0);c.restore();health(c,a,a.y-79,32);if(a.type===f.selected&&f.panelOpen){c.strokeStyle='#ecd39388';c.lineWidth=1;c.beginPath();c.ellipse(a.x,a.y+3,18,6,0,0,Math.PI*2);c.stroke();}if(a.hp<=0)label(c,'待救护',a.x,a.y+15,'#c2c1ad',10);});
 add(b.pump,()=>{const a=b.pump;sprite(c,assets.facilities,'facilities',a.hp/a.max<.4?1:0,a.x,a.y,.25);health(c,a,a.y-128,72);if(!reduced){c.fillStyle='#a8d7d3bb';const u=b.time%1;c.fillRect(a.x-34,a.y-43+u*17,2,4);c.fillRect(a.x-29,a.y-39+(u+.5)%1*17,2,3);}if(b.pumpHit>0)label(c,'净水泵受袭',a.x,a.y-144,'#f1a08b');});return layers;
}
export function drawBattleEffects(c,b,reduced=false){
 for(const s of b.front?.shots||[]){c.save();const u=Math.min(1,s.age/(s.flight||.5)),height=(s.kind==='tower'?88:32)*(1-u)+30*u;c.translate(s.x,s.y-height);c.rotate(s.angle);if(s.kind==='tower'){c.fillStyle='#ffe6a0';c.beginPath();c.ellipse(0,0,7,4,0,0,Math.PI*2);c.fill();c.strokeStyle='#d6b56e99';c.lineWidth=2;c.beginPath();c.moveTo(-17,0);c.lineTo(-4,0);c.stroke();}else{c.strokeStyle='#e9dcad';c.lineWidth=2;c.beginPath();c.moveTo(-14,0);c.lineTo(3,0);c.stroke();c.fillStyle='#9dbdc0';c.beginPath();c.moveTo(6,0);c.lineTo(0,-3);c.lineTo(0,3);c.fill();}c.restore();}
 const q=b.pulseWave;if(q){c.save();if(q.age<.15){c.strokeStyle='#ffe2a2';c.lineWidth=2;c.beginPath();c.arc(q.x,q.y-46,5+q.age*30,0,Math.PI*2);c.stroke();}else{const radius=Math.min(200,(q.age-.15)/.25*200);c.globalAlpha=q.age>.4?Math.max(0,(.55-q.age)/.15):.8;c.lineWidth=3;c.strokeStyle='#f3d68a';c.beginPath();c.arc(q.x,q.y,radius,0,Math.PI*2);c.stroke();c.strokeStyle='#fff1bc66';c.lineWidth=1;c.beginPath();c.arc(q.x,q.y,Math.max(0,radius-7),0,Math.PI*2);c.stroke();}c.restore();}
 for(const fx of [...b.contacts,...(b.front?.impacts||[])]){c.save();c.translate(fx.x,fx.y);c.globalAlpha=Math.min(1,fx.life*5);c.strokeStyle=fx.kind==='pulse'?'#f7e6ab':fx.kind==='block'?'#eff3db':'#e8ca8d';c.lineWidth=2;if(fx.kind==='miss'){c.beginPath();c.moveTo(-7,0);c.lineTo(7,0);c.stroke();}else for(let i=0;i<4;i++){const a=i*Math.PI/2+.4,extent=reduced?8:6+(1-fx.life/.3)*8;c.beginPath();c.moveTo(Math.cos(a)*3,Math.sin(a)*3);c.lineTo(Math.cos(a)*extent,Math.sin(a)*extent);c.stroke();}c.restore();}
}
// Camera-space calculation is shared by rendering and tests; targets in view have no edge marker.
export function incomingHints(b,{ox,oy,scale,vw,vh}){const hints=[],groups=new Map(),cx=vw/2,cy=vh/2,left=24,right=Math.max(25,vw-24),top=Math.min(150,vh*.25),bottom=Math.max(top+20,vh-120);
 const position=(x,y)=>{const dx=x-cx,dy=y-cy,t=Math.min(1,dx>0?(right-cx)/dx:dx<0?(left-cx)/dx:Infinity,dy>0?(bottom-cy)/dy:dy<0?(top-cy)/dy:Infinity);return {x:clamp(cx+dx*t,left,right),y:clamp(cy+dy*t,top,bottom),angle:Math.atan2(dy,dx)};};
 for(const e of b.enemies){if(e.hp<=0)continue;const x=ox+e.x*scale,y=oy+e.y*scale;if(x+22*scale>=0&&x-22*scale<=vw&&y>=0&&y-90*scale<=vh)continue;const pos=position(x,y),sector=Math.round(pos.angle/(Math.PI/4));const key=(sector+8)%8;if(!groups.has(key))groups.set(key,{...pos,count:0,kind:'enemy'});groups.get(key).count++;}hints.push(...groups.values());
 if(b.front?.warning>0){const w=WAVES[b.front.wave-1];for(const lane of w.lanes){const count=w.types.filter((_,i)=>w.lanes[i%w.lanes.length]===lane).length;hints.push({...position(ox+(lane==='west'?290:1380)*scale,oy+350*scale),count,kind:'wave',label:lane==='west'?'西渠':'东堤'});}}if(b.operation?.warning>0){for(const lane of ['west','east']){const count=b.operation.queue.filter(q=>q.lane===lane).length;if(count)hints.push({...position(ox+(lane==='west'?300:1370)*scale,oy+400*scale),count,kind:'wave',label:lane==='west'?'西侧':'东侧'});}}return hints;
}
export function drawIncoming(c,b,view){for(const h of incomingHints(b,view)){c.save();c.translate(h.x,h.y);c.rotate(h.angle);c.fillStyle=h.kind==='wave'?'#f0ce89':'#d9947d';c.strokeStyle='#24362e';c.lineWidth=2;c.beginPath();c.moveTo(9,0);c.lineTo(-5,-6);c.lineTo(-2,0);c.lineTo(-5,6);c.closePath();c.fill();c.stroke();c.restore();const dx=h.x<view.vw/2?40:-40;label(c,h.kind==='wave'?`${h.label} ${h.count} · 将至`:`${h.count}`,h.x+dx,h.y+4,h.kind==='wave'?'#f7dda5':'#efb09c',11);}}
